const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const categories=['上装','下装','连衣裙','外套','鞋履','包袋','配饰'],colors=['黑色','白色','灰色','米色','棕色','蓝色','绿色','红色','粉色','黄色','紫色','多色'],seasons=['春季','夏季','秋季','冬季'],occasions=['日常','工作','约会','旅行','正式','运动'],statuses=['Available','Laundry','Storage','Borrowed'];
