const seedWear=[18,9,24,3,16,7,5,2,14,6,11,0],seedAgo=[3,18,1,82,5,25,48,95,9,36,14,null],seedStatus=['Available','Laundry','Available','Storage','Available','Available','Available','Storage','Available','Borrowed','Available','Available'];
const seedItems=names.map((name,i)=>({id:'item-'+i,name,image:ASSETS['clothing-'+i],category:cats[i],color:shades[i],season:i%3===0?['秋季','冬季']:i%3===1?['春季','夏季']:['春季','秋季'],occasion:i%4===0?['日常','工作']:i%4===1?['工作','正式']:['日常','旅行'],favorite:[0,2,4,8,10].includes(i),wearCount:seedWear[i],lastWornAt:seedAgo[i]===null?undefined:new Date(Date.now()-seedAgo[i]*86400000).toISOString(),status:seedStatus[i],material:['亚麻','羊毛','牛仔布','棉','纯棉'][i%5],size:['S','M','L'][i%3],notes:'',createdAt:new Date(Date.now()-i*9*86400000).toISOString()}));
const seedOutfits=[['周日咖啡',[4,2,8,10],'日常','春季'],['极简通勤',[0,5,9],'工作','春季'],['秋日城市',[6,2,3],'日常','秋季'],['晚餐时刻',[1,7,9],'约会','秋季']].map((r,i)=>({id:'outfit-'+i,name:r[0],items:compose(r[1].map(n=>'item-'+n)),occasion:r[2],season:r[3],createdAt:new Date().toISOString()}));
let memoryOnly=false;const keys={items:'wardrobe_items',outfits:'wardrobe_outfits',inspirations:'wardrobe_inspirations',logs:'wardrobe_wear_logs',profile:'wardrobe_body_profile'};
