  if(!hasBaseline&&usage.last&&baseLast?.slice(0,10)===usage.last)baseLast=null;
  const latest=[baseLast?.slice(0,10),usage.last].filter(Boolean).sort().at(-1);
  return {...item,season:item.season||[],occasion:item.occasion||[],wearCount:baseCount+usage.count,lastWornAt:latest,
    _usageBaseCount:baseCount,_usageBaseLastWornAt:baseLast||null,
    status:normalizeStatus(item.status||sample?.status),favorite:Boolean(item.favorite),material:item.material||'',size:item.size||'',notes:item.notes||''};
