data.items=data.items.map(item=>normalizeItem(item,data.logs));
try{localStorage.setItem(keys.items,JSON.stringify(data.items));}catch{memoryOnly=true;}
let toastTimer,modalCleanup=()=>{},editor=null,category='全部',search='',activeSmart='',filters={category:[],color:[],season:[],occasion:[],status:[],usage:[]},showFilters=false,period='week',anchor=dateKey();
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3300);}
function save(patch){if(Object.hasOwn(patch,'logs'))patch={...patch,items:reconcileUsage(patch.items||data.items,patch.logs)};const next={...data,...patch};let previous={};try{for(const k of Object.keys(patch))previous[k]=localStorage.getItem(keys[k]);for(const k of Object.keys(patch))localStorage.setItem(keys[k],JSON.stringify(next[k]));data=next;return true;}catch{try{for(const k of Object.keys(previous))previous[k]===null?localStorage.removeItem(keys[k]):localStorage.setItem(keys[k],previous[k]);}catch{}toast('保存失败：浏览器存储不足或不可用，请换用更小的图片。');return false;}}
function go(route){location.hash=route;}
function route(){return decodeURIComponent(location.hash.slice(1)||'/');}
function icon(name){const paths={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',shirt:'<path d="m8 3-5 3-2 5 5 2v8h12v-8l5-2-2-5-5-3q-4 5-8 0Z"/>',outfit:'<path d="m12 3 10 5-10 5L2 8Z"/><path d="m2 12 10 5 10-5M2 16l10 5 10-5"/>',inspiration:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5Z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',plus:'<path d="M12 5v14M5 12h14"/>'};return `<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.shirt}</svg>`;}
function header(title,sub,label,action){return `<header class="page-header"><div><div class="eyebrow">我的电子衣橱</div><h1>${title}</h1><p>${sub}</p></div>${label?`<button class="button" data-action="${action}">${icon('plus')}${label}</button>`:''}</header>`;}
function back(url,label){return `<a class="back" href="#${url}">← ${label}</a>`;}
