function dashboard(){const today=data.logs.filter(l=>l.date===dateKey()),featured=data.outfits[0];const visual=featured?preview(featured):`<div class="home-hero-items">${data.items.slice(0,3).map(i=>`<img src="${esc(i.image)}" alt="${esc(i.name)}">`).join('')}</div>`;return `<section class="home-hero"><div class="home-hero-copy"><div class="eyebrow">我的电子衣橱</div><h1>衣橱，<br>终于一目了然。</h1><p>看见拥有的，创造今天要穿的，收藏让你心动的灵感。</p><button class="button" data-action="add-item">${icon('plus')}添加衣物</button></div><div class="home-hero-visual">${visual}<span>${featured?esc(featured.name):'属于你的日常衣橱'}</span></div></section>`+homeWeek()+`<div class="summary">${[[data.items.length,'件衣物'],[data.outfits.length,'套搭配'],[data.inspirations.length,'份灵感']].map(([n,l])=>`<div><strong>${n}</strong><span>${l}</span></div>`).join('')}<p>认真收藏每一件。<br>让风格属于自己。</p></div><section class="today-section"><div class="section-heading"><div><div class="eyebrow">${dateKey()} · 日常风格日记</div><h2>今日穿搭记录</h2></div><button class="button secondary" data-action="add-log">＋ 记录今日穿搭</button></div>${today.length?`<div class="logs-grid">${today.map(recordCard).join('')}</div>`:`<div class="today-empty"><div class="day-sun" aria-hidden="true">☀</div><div><h3>今天，穿了什么？</h3><p>从已保存的搭配或衣橱单品开始，留住今天的风格。</p></div><button class="text-button" data-action="add-log">开始记录 →</button></div>`}<a class="text-button" href="#/me">查看我的穿搭日志 →</a></section>`+(!data.items.length&&!data.outfits.length&&!data.inspirations.length?empty('你的衣橱，从这里开始。','添加一件你已经喜欢的衣物。','添加第一件衣物','add-item'):section('最近添加','/wardrobe','查看衣橱',`<div class="clothing-grid home-clothes">${data.items.slice(0,4).map(clothingCard).join('')}</div>`)+section('我的搭配','/outfits','查看搭配',`<div class="outfit-grid">${data.outfits.slice(0,3).map(outfitCard).join('')}</div>`)+section('最新灵感','/inspiration','查看灵感',`<div class="home-inspiration">${data.inspirations.slice(0,4).map(inspirationCard).join('')}</div>`));}
function tabs(){return `<div class="tabs">${['全部',...categories].map(c=>`<button data-action="category" data-value="${c}" class="${category===c?'selected':''}">${c}</button>`).join('')}</div>`;}
function options(list,value){return list.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(statusLabels[v]||v)}</option>`).join('');}
function olderThan(i,days){return !i.lastWornAt||Date.now()-new Date(i.lastWornAt).getTime()>days*86400000;}
function searchMatches(i,q){if(!q.trim())return true;const aliases={上装:'tops top',下装:'bottoms bottom',连衣裙:'dresses dress',外套:'outerwear coat',鞋履:'shoes shoe',包袋:'bags bag',配饰:'accessories accessory',黑色:'black',白色:'white',灰色:'gray grey',米色:'beige',棕色:'brown',蓝色:'blue',绿色:'green',红色:'red',粉色:'pink',黄色:'yellow',紫色:'purple',日常:'everyday casual',工作:'work',约会:'date',旅行:'travel',正式:'formal',运动:'sport',春季:'spring',夏季:'summer',秋季:'autumn fall',冬季:'winter'};const text=[i.name,i.category,i.color,i.brand,...i.occasion,...i.season].map(v=>`${v||''} ${aliases[v]||''}`).join(' ').toLowerCase();return q.toLowerCase().trim().split(/\s+/).every(word=>text.includes(word));}
function usageMatch(i,values){return !values.length||values.some(v=>v==='从未穿过'?i.wearCount===0:v==='很少穿'?i.wearCount>0&&i.wearCount<5:i.wearCount>=5);}
