function clothingDetail(cid){const i=data.items.find(i=>i.id===cid);if(!i)return missing('/wardrobe');const used=data.outfits.filter(o=>o.items.some(c=>c.clothingId===cid));return back('/wardrobe','返回衣橱')+`<div class="detail-layout"><div class="detail-clothing"><img src="${esc(i.image)}" alt="${esc(i.name)}"></div><div class="detail-copy"><div class="eyebrow">我的收藏</div><h1>${esc(i.name)}</h1><p class="detail-category">${esc(i.category)} · ${esc(i.color)}</p><dl>${[['品牌',i.brand||'—'],['季节',i.season.join('、')||'—'],['场合',i.occasion.join('、')||'—'],['材质',i.material||'—'],['尺码',i.size||'—']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}<div><dt>状态</dt><dd><select class="status-select" data-status-id="${cid}" aria-label="衣物状态">${options(statuses,i.status)}</select></dd></div></dl>${i.notes?`<p class="notes">${esc(i.notes)}</p>`:''}<div class="actions"><button class="button" data-action="edit-item" data-id="${cid}">编辑衣物</button><button class="button secondary" data-action="delete-item" data-id="${cid}">删除</button></div></div></div><section class="activity-section"><div class="section-heading"><h2>衣橱活动</h2></div><div class="activity-grid"><div><strong>${i.wearCount}</strong><span>穿着次数</span></div><div><strong>${i.lastWornAt?new Date(i.lastWornAt).toLocaleDateString('zh-CN'):'尚未穿过'}</strong><span>最近穿着</span></div><div><strong>${new Date(i.createdAt).toLocaleDateString('zh-CN')}</strong><span>添加日期</span></div></div></section><section class="used-section"><div class="section-heading"><h2>用于搭配</h2></div>${used.length?`<div class="outfit-grid">${used.map(outfitCard).join('')}</div>`:'<p class="muted">这件单品还没有用于任何搭配。</p>'}<button class="button create-with-item" data-action="create-with-item" data-id="${cid}">用这件单品创建搭配</button></section>`;}
