function shiftPeriod(dir){const d=parseDate(anchor);if(period==='week')d.setDate(d.getDate()+dir*7);else if(period==='month')d.setFullYear(d.getFullYear(),d.getMonth()+dir,1);else d.setFullYear(d.getFullYear()+dir,0,1);anchor=dateKey(d);render();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,cid=el.dataset.id;switch(a){case 'journal-date':anchor=el.dataset.date;period='week';go('/me');break;case 'camera':cameraModal();break;case 'close-modal':closeModal();break;case 'add-item':clothingModal();break;case 'batch-add':batchModal();break;case 'edit-item':clothingModal(cid);break;case 'favorite':if(save({items:data.items.map(i=>i.id===cid?{...i,favorite:!i.favorite}:i)}))render();break;case 'category':category=el.dataset.value;render();break;case 'smart':activeSmart=activeSmart===el.dataset.value?'':el.dataset.value;category='全部';render();break;case 'filters':showFilters=!showFilters;render();break;case 'reset-filter':filters={category:[],color:[],season:[],occasion:[],status:[],usage:[]};render();break;case 'delete-item':confirmDelete('删除这件衣物？','这件衣物也会从已保存的搭配中移除。历史穿搭记录保留当时的单品快照。',()=>{if(save({items:data.items.filter(i=>i.id!==cid),outfits:data.outfits.map(o=>({...o,items:o.items.filter(i=>i.clothingId!==cid)}))})){toast('衣物已删除');go('/wardrobe');}else return false;});break;case 'new-outfit':go('/outfits/new');break;case 'create-with-item':editor=null;go('/outfits/new?item='+encodeURIComponent(cid));break;case 'save-outfit':if(!editor.items.length){toast('请先添加至少一件衣物');break;}const o={id:editor.id||id(),name:editor.name.trim()||'未命名搭配',items:editor.items,occasion:editor.occasion,season:editor.season,createdAt:data.outfits.find(o=>o.id===editor.id)?.createdAt||new Date().toISOString()};if(save({outfits:editor.id?data.outfits.map(v=>v.id===editor.id?o:v):[o,...data.outfits]})){toast('搭配已保存');go('/outfits');}break;case 'delete-outfit':confirmDelete('删除这套搭配？','这套搭配将从搭配库移除，已记录的历史穿搭保留。',()=>{if(save({outfits:data.outfits.filter(o=>o.id!==cid)})){toast('搭配已删除');go('/outfits');}else return false;});break;case 'canvas-add':editor.items.push({clothingId:cid,x:190,y:210,width:220,height:280,rotation:0,zIndex:Math.max(0,...editor.items.map(i=>i.zIndex))+1});editor.selected=editor.items.length-1;updateCanvas();break;case 'canvas-delete':confirmDelete('移除这件单品？','从当前画布中移除，不影响衣橱中的衣物。',()=>{editor.items.splice(editor.selected,1);editor.selected=null;updateCanvas();});break;case 'forward':editor.items[editor.selected].zIndex=Math.max(...editor.items.map(i=>i.zIndex))+1;updateCanvas();break;case 'backward':editor.items[editor.selected].zIndex=Math.min(...editor.items.map(i=>i.zIndex))-1;updateCanvas();break;case 'picker-category':editor.category=el.dataset.value;$('#picker-items').innerHTML=pickerItems();$$('.picker .tabs button').forEach(b=>b.classList.toggle('selected',b===el));break;case 'add-inspiration':inspirationModal();break;case 'delete-inspiration':confirmDelete('删除这份灵感？','这张图片将从你的灵感收藏中移除。',()=>{if(save({inspirations:data.inspirations.filter(i=>i.id!==cid)})){toast('灵感已删除');go('/inspiration');}else return false;});break;case 'recreate':editor=null;go('/outfits/new?inspired=1');break;case 'profile':profileModal();break;case 'add-log':logModal();break;case 'edit-log':logModal(cid);break;case 'record-outfit':logModal(null,cid);break;case 'delete-log':confirmDelete('删除这条穿搭记录？','这次穿着将不再计入对应周期的日志与爱用单品统计。',()=>{if(save({logs:data.logs.filter(l=>l.id!==cid)})){toast('穿搭记录已删除');}else return false;});break;case 'period':period=el.dataset.value;render();break;case 'previous-period':shiftPeriod(-1);break;case 'next-period':shiftPeriod(1);break;case 'current-period':anchor=dateKey();render();break;case 'settings':openModal('设置','<p class="muted">你的衣橱和身材数据保存在当前浏览器中，无需注册账号。真实 AI 尚未接入，上传识别为可修改的模拟结果。</p><button class="button" data-action="close-modal">知道了</button>');break;}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='wardrobe-search'){const pos=el.selectionStart;search=el.value;render();$('#wardrobe-search').focus();$('#wardrobe-search').setSelectionRange(pos,pos);}if(el.id==='picker-search'){editor.search=el.value;$('#picker-items').innerHTML=pickerItems();}if(editor&&el.name==='outfitName')editor.name=el.value;});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.filter){const drawer=$('.filter-drawer'),scroll=drawer.scrollTop,key=el.dataset.filter,value=el.value;const values=new Set(filters[el.dataset.filter]);el.checked?values.add(el.value):values.delete(el.value);filters[el.dataset.filter]=[...values];render();$('.filter-drawer').scrollTop=scroll;$('.filter-drawer input[data-filter="'+key+'"][value="'+value+'"]').focus({preventScroll:true});}if(el.dataset.statusId){if(save({items:data.items.map(i=>i.id===el.dataset.statusId?{...i,status:el.value}:i)})){toast('衣物状态已更新');render();}}if(el.id==='anchor-date'&&el.value){anchor=el.value;render();}if(editor&&el.name==='outfitOccasion')editor.occasion=el.value;if(editor&&el.name==='outfitSeason')editor.season=el.value;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&showFilters){showFilters=false;render();$('[data-action="filters"]')?.focus();}});
window.addEventListener('hashchange',()=>{closeModal();showFilters=false;category='全部';search='';render();window.scrollTo(0,0);});if(location.hash&&location.hash!=='#/')history.replaceState(null,'',location.pathname+location.search+'#/');render();if(memoryOnly)toast('浏览器存储不可用；请允许本地存储后再保存数据。');
